import xml.etree.ElementTree as ET

ns = {'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

# golden
tree = ET.parse('/tmp/goldx/xl/worksheets/sheet1.xml')
root = tree.getroot()
sst_tree = ET.parse('/tmp/goldx/xl/sharedStrings.xml')
sst_root = sst_tree.getroot()
shared = [ ''.join(t.text or '' for t in si.findall('.//m:t', ns)) for si in sst_root.findall('m:si', ns) ]
print('shared count', len(shared))
print(shared)

def col_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters = m.group(1); row = int(m.group(2))
    c = 0
    for ch in letters:
        c = c*26 + (ord(ch)-ord('A')+1)
    return c, row

def is_in_range(ref):
    c,r = col_idx(ref)
    return r>=2 and r<=10 and c>=2 and c<=31  # B=2, AE=31

