# Build the golden-equivalent by taking the input template XML and injecting values at target cells,
# but compare to input template (which is same as golden minus values/inline strings).
# We already have ourx. Let's compare ourx sheet1.xml vs golden sheet1.xml ignoring:
# - <v> values inside formula cells (we leave empty, golden has cached)
# - shared formula attributes (si/ref) 
# - t="inlineStr" vs t="s" representation
# - AE5 formula vs our static value
# - style s index mapping (golden uses different style table) - not in sheet1, but style refs will differ everywhere.
# So instead compare only the value-level content we injected. Let's list cells and their values from golden vs ours.
import re, xml.etree.ElementTree as ET
from openpyxl.utils import get_column_letter
ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

def parse(path, shared_path=None):
    tree=ET.parse(path); root=tree.getroot()
    sst = ET.parse(shared_path).getroot() if shared_path else None
    shared=[]
    if sst is not None:
        shared=[''.join(t.text or '' for t in si.findall('.//m:t',ns)) for si in sst.findall('m:si',ns)]
    out={}
    for cell in root.findall('.//m:row/m:c',ns):
        ref=cell.get('r')
        if not ref: continue
        m=re.match(r'([A-Z]+)(\d+)',ref); r=int(m.group(2)); c=0
        for ch in m.group(1): c=c*26+ord(ch)-64
        if not (2<=r<=10 and 2<=c<=31): continue
        f=cell.find('m:f',ns); v=cell.find('m:v',ns); is_el=cell.find('m:is',ns); t=cell.get('t')
        if f is not None:
            out[ref]='FORMULA:'+''.join(f.itertext())
        elif is_el is not None:
            out[ref]='STR:'+''.join(t.text or '' for t in is_el.findall('.//m:t',ns))
        elif v is not None and v.text is not None:
            if t=='s': out[ref]='STR:'+shared[int(v.text)]
            else: out[ref]='NUM:'+v.text
        else:
            out[ref]='EMPTY'
    return out

g=parse('/tmp/goldx/xl/worksheets/sheet1.xml','/tmp/goldx/xl/sharedStrings.xml')
o=parse('/tmp/ourx/xl/worksheets/sheet1.xml')
# normalize formula text (golden AE5 array)
g2={}
for k,v in g.items():
    if v.startswith('FORMULA:'):
        g2[k]='FORMULA:'+v.split(':',1)[1].strip()
    else:
        g2[k]=v
o2={}
for k,v in o.items():
    if v.startswith('FORMULA:'):
        o2[k]='FORMULA:'+v.split(':',1)[1].strip()
    else:
        o2[k]=v
diffs=[]
for k in sorted(set(g2)|set(o2)):
    gv=g2.get(k,'<none>'); ov=o2.get(k,'<none>')
    # allow AE5 formula vs value difference, and formula cached values (NUM vs FORMULA) - skip formula cells
    if gv.startswith('FORMULA:') or ov.startswith('FORMULA:'):
        # compare formula text if both present
        continue
    if gv!=ov:
        diffs.append((k,gv,ov))
print('value diffs (excluding formulas):', len(diffs))
for d in diffs: print(d)
